INSERT INTO `wp8t_posts` VALUES (4,0,'2024-09-18 08:19:38','2024-09-18 08:19:38','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2024-09-18 08:19:38','2024-09-18 08:19:38','',0,'https://famed-falguni-m2ypw.zipwp.top/navigation/',0,'wp_navigation','',0),(9,4,'2026-01-26 13:40:31','2026-01-26 17:40:31','<div class=\"wp-block-uagb-container uagb-block-efd6ebae alignfull uagb-is-root-container\">\n<div class=\"uagb-container-inner-blocks-wrap\">\n<div class=\"wp-block-uagb-info-box uagb-block-46ab5502 uagb-infobox__content-wrap  uagb-infobox-icon-above-title uagb-infobox-image-valign-top wp-block-uagb-info-box--has-margin\">\n<div class=\"uagb-infobox-margin-wrapper\">\n<div class=\"uagb-ifb-content\">\n<div class=\"uagb-ifb-separator\"></div>\n<div class=\"uagb-ifb-title-wrap\">\n<h1 class=\"uagb-ifb-title\">Ingeniería con compromiso social y ético</h1>\n</div>\n<p class=\"uagb-ifb-desc\">Promovemos el desarrollo técnico y ético de la ingeniería en La Paz, apoyando el crecimiento profesional de nuestros socios.</p>\n<div class=\"uagb-ifb-button-wrapper wp-block-button\"><a href=\"/contact\" class=\"uagb-infobox-cta-link wp-block-button__link\" target=\"_self\" rel=\"noopener noreferrer\" onclick=\"return true;\"><span class=\"uagb-inline-editing\">Únete ahora</span></a></div>\n</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-e9a4389c alignfull uagb-is-root-container\">\n<div class=\"uagb-container-inner-blocks-wrap\">\n<div class=\"wp-block-uagb-info-box uagb-block-f98ca771 uagb-infobox__content-wrap  uagb-infobox-icon-above-title uagb-infobox-image-valign-top wp-block-uagb-info-box--has-margin\">\n<div class=\"uagb-infobox-margin-wrapper\">\n<div class=\"uagb-ifb-content\">\n<div class=\"uagb-ifb-separator\"></div>\n<div class=\"uagb-ifb-title-wrap\">\n<h2 class=\"uagb-ifb-title\">Conoce nuestra sociedad de ingenieros</h2>\n</div>\n<p class=\"uagb-ifb-desc\">La Sociedad de Ingenieros de Bolivia – Departamental La Paz, se enfoca en promover la ética y el profesionalismo en la ingeniería.</p>\n<div class=\"uagb-ifb-button-wrapper wp-block-button\"><a href=\"/about\" class=\"uagb-infobox-cta-link ast-outline-button\" target=\"_self\" rel=\"noopener noreferrer\" style=\"border-width:revert-layer\" onclick=\"return true;\"><span class=\"uagb-inline-editing\">Leer Más</span></a></div>\n</div>\n</div>\n</div>\n<div class=\"wp-block-uagb-container uagb-layout-flex uagb-block-314d5080\">\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-4c148051\">\n<div class=\"wp-block-uagb-counter uagb-block-2887fc81 wp-block-uagb-counter--number\">\n<div class=\"wp-block-uagb-counter__number\"><span class=\"uagb-counter-block-number\" data-duration=\"1.5\" data-to-value=\"10\" data-from-value=\"0\" data-delimiter=\",\"></span><span class=\"uagb-counter-block-suffix\">+</span></div>\n<div class=\"wp-block-uagb-counter__title\">Años deu003cbru003eExperiencia</div>\n</div>\n<div class=\"wp-block-uagb-counter uagb-block-5016208e wp-block-uagb-counter--number\">\n<div class=\"wp-block-uagb-counter__number\"><span class=\"uagb-counter-block-number\" data-duration=\"1.5\" data-to-value=\"200\" data-from-value=\"0\" data-delimiter=\",\"></span><span class=\"uagb-counter-block-suffix\">+</span></div>\n<div class=\"wp-block-uagb-counter__title\">Proyectosu003cbru003eCompletados</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-0b4fe1fa alignfull uagb-is-root-container\">\n<div class=\"uagb-container-inner-blocks-wrap\">\n<div class=\"wp-block-uagb-advanced-heading uagb-block-c537b339\">\n<div class=\"uagb-separator\"></div>\n<h2 class=\"uagb-heading-text\">Servicios que ofrecemos a nuestros socios</h2>\n</div>\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-aa24d0e8 alignfull uagb-is-root-container\">\n<div class=\"uagb-container-inner-blocks-wrap\">\n<div class=\"wp-